   for i,(x,y) in enumerate(original_pts):opening=opening.replace(f'({x},{y})',f'<<P{i}>>')
   for i,(x,y) in enumerate(p['points']):opening=opening.replace(f'<<P{i}>>',f'({x},{y})')
