# Easy observed/source domains, moderate and hard authored domains.
def generate(level,seed=0,template=None,field_type=None,parameters=None,profile=None):
 if level not in ('easy','moderate','hard'):raise ValueError('Unknown difficulty')
 if field_type not in (None,'radio',':answer-field.type/radio'):raise ValueError('Radio only')
 profile=profile or 'authored'
 if profile not in ('authored',*PROFILES):raise ValueError('Unknown bank profile')
 r=random.Random(seed)
 eligible=TEMPLATES if level!='hard' else ('two_quadratic','rational_square','affine_fraction')
 t=template or (PROFILES[profile][0] if profile!='authored' else r.choice(eligible))
 if profile!='authored' and t!=PROFILES[profile][0]:raise ValueError('Profile/template mismatch')
 for attempt in range(1000):
  p=dict(parameters) if parameters is not None else sample(level,t,r)
  try:validate_parameters(level,t,p);s,bank=banks(t,p,profile);break
  except ValueError:
   if parameters is not None:raise
 else:raise ValueError('No valid whole bank')
 p={k:([[int(sp.Rational(v)) if sp.Rational(v).q==1 else str(sp.Rational(v)) for v in pt] for pt in value] if k=='points' else str(sp.Rational(value))) for k,value in p.items()}
 canonical={k:([list(pt) for pt in v] if k=='points' else str(sp.Rational(v))) for k,v in p.items()}
 ci=bank.index(s);assets=render_plots({'points':p['points'],'bank':bank,'correct_index':ci})
 problem,solution,rows=presentation(t,p,profile,s,assets,level)
 task=digest({'equation':str(eq(t,p)),'points':sorted(p['points'])})
 identity=digest({'version':VERSION,'level':level,'problem':problem,'solution':solution,'bank':sorted(assets['choices'])})
 fid=uid(identity+'field');answers=[{':answer/id':uid(fid+'answer:'+v),':answer/type':':answer.type/image',':answer/value':v} for v in assets['choices']]
 correct=answers[ci][':answer/id'];r.shuffle(answers)
 return {'knowledge_point':{'db_id':KP_ID,'id':KP_UUID,'title':TITLE},'question':{':question/id':uid(identity),':question/difficulty':':question.difficulty/'+level,':question/problem':problem,':question/worked-solution':solution,':question/answer-fields':[{':answer-field/id':fid,':answer-field/key':'selection',':answer-field/type':':answer-field.type/radio',':answer-field/choices':answers,':answer-field/correct':[':answer/id',correct]}]},'generation':{'version':VERSION,'template':t,'bank_profile':profile,'seed':seed,'parameters':canonical,'source':{k:SOURCE[k] for k in ('database','basis','lineage')},'source_ids':[profile] if profile!='authored' else [],'authored':profile=='authored' or level!='easy','mathematical_fingerprint':task,'content_fingerprint':identity,'exact_slopes':list(map(str,s)),'choice_geometry':{path:list(map(str,row)) for path,row in zip(assets['choices'],bank)},'worked_rows':rows,'domain':{'point_count':3,'equation':str(eq(t,p)),'x_nonzero':t=='rational_square'}}}
